css:
.fx-drw{width:min(560px,100%)}
.fx-drw .stage{position:relative;height:460px;border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:var(--surface)}
.fx-drw .main{padding:1.4em}.fx-drw .main p{opacity:.65;margin:.5em 0 1.2em}
.fx-drw .btns{display:flex;gap:.6em;flex-wrap:wrap}
.fx-drw .btns button{padding:.7em 1.3em;border-radius:99px;border:1px solid var(--primary);background:none;color:var(--primary);font:700 .9em var(--font-body);cursor:pointer}
.fx-drw .btns button:first-child{background:var(--primary);color:var(--on-primary)}
.fx-drw .ov{position:absolute;inset:0;background:color-mix(in srgb,var(--text) 45%,transparent);opacity:0;visibility:hidden;transition:opacity calc(.3s/var(--speed));z-index:4}
.fx-drw.open .ov{opacity:1;visibility:visible}
.fx-drw .dr{position:absolute;z-index:5;background:var(--surface);color:var(--text);display:flex;flex-direction:column;visibility:hidden;transition:transform calc(.38s/var(--speed)) cubic-bezier(.2,.8,.2,1),visibility 0s calc(.38s/var(--speed));box-shadow:0 0 40px color-mix(in srgb,#000 30%,transparent)}
.fx-drw.open .dr{visibility:visible;transform:none!important;transition:transform calc(.38s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-drw .dr[data-s=right]{top:0;bottom:0;right:0;width:min(300px,86%);transform:translateX(100%)}
.fx-drw .dr[data-s=left]{top:0;bottom:0;left:0;width:min(300px,86%);transform:translateX(-100%)}
.fx-drw .dr[data-s=bottom]{left:0;right:0;bottom:0;height:var(--h,50%);border-radius:1.4em 1.4em 0 0;transform:translateY(100%)}
.fx-drw .dr.drag{transition:none!important}
.fx-drw .hd{display:flex;justify-content:space-between;align-items:center;padding:1em 1.2em;border-bottom:1px solid var(--border)}
.fx-drw .hd h3{font-size:1.15em}
.fx-drw .x{width:2.2em;height:2.2em;border-radius:50%;border:0;background:color-mix(in srgb,var(--text) 8%,var(--surface));color:var(--text);cursor:pointer;font-size:1.1em}
.fx-drw .grip{display:none;padding:.7em 0 .2em;cursor:grab;touch-action:none}
.fx-drw .grip::before{content:"";display:block;width:2.6em;height:.28em;border-radius:99px;background:var(--border);margin:auto}
.fx-drw .dr[data-s=bottom] .grip{display:block}
.fx-drw .bd{padding:1.1em 1.2em;overflow:auto;flex:1;display:grid;gap:.5em;align-content:start}
.fx-drw .bd a,.fx-drw .bd label{display:flex;justify-content:space-between;padding:.75em .9em;border:1px solid var(--border);border-radius:calc(var(--radius)*.6);text-decoration:none;color:var(--text);font-weight:600}
.fx-drw .bd a:hover{border-color:var(--primary)}
@media(prefers-reduced-motion:reduce){.fx-drw .dr,.fx-drw .ov{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-drw .bd a.is-tap{border-color:var(--primary)}

