(function(){var r=document.querySelector('.fx-drw'),dr=r.querySelector('.dr'),ov=r.querySelector('.ov'),T=r.querySelector('#fx-drw-t'),B=r.querySelector('#fx-drw-b'),last=null;
var C={right:['Filters','<label>In stock only <input type="checkbox"></label><label>Under RM 500 <input type="checkbox"></label><label>Made to order <input type="checkbox"></label><a href="#" onclick="return false">Show 48 results</a>'],
 left:['Menu','<a href="#" onclick="return false">Shop all</a><a href="#" onclick="return false">New in</a><a href="#" onclick="return false">Journal</a><a href="#" onclick="return false">Contact</a>'],
 bottom:['Share','<a href="#" onclick="return false">Copy link</a><a href="#" onclick="return false">WhatsApp</a><a href="#" onclick="return false">Email</a><a href="#" onclick="return false">More options</a>']};
function foc(){return [].slice.call(dr.querySelectorAll('a[href],button,input,select,textarea,[tabindex]:not([tabindex="-1"])')).filter(function(x){return !x.disabled})}
function open(s,btn){last=btn;dr.dataset.s=s;dr.style.removeProperty('--h');dr.classList.remove('full');T.textContent=C[s][0];B.innerHTML=C[s][1];dr.style.transform='';r.classList.add('open');setTimeout(function(){var f=foc();(f[1]||f[0]).focus({preventScroll:true})},60)}
function close(){r.classList.remove('open');if(last)last.focus({preventScroll:true})}
r.querySelectorAll('[data-o]').forEach(function(b){b.onclick=function(){open(b.dataset.o,b)}});
r.querySelector('.x').onclick=close;ov.onclick=close;
r.addEventListener('keydown',function(e){if(!r.classList.contains('open'))return;if(e.key==='Escape'){close();return}
 if(e.key==='Tab'){var f=foc();if(!f.length)return;var a=f[0],z=f[f.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}}});
/* drag the bottom sheet */
var g=dr.querySelector('.grip'),y0=null,dy=0,t0=0;
g.addEventListener('pointerdown',function(e){y0=e.clientY;dy=0;t0=Date.now();dr.classList.add('drag');g.setPointerCapture(e.pointerId)});
g.addEventListener('pointermove',function(e){if(y0===null)return;dy=Math.max(-80,e.clientY-y0);dr.style.transform='translateY('+Math.max(0,dy)+'px)'});
function end(){if(y0===null)return;var h=dr.offsetHeight,v=dy/Math.max(1,Date.now()-t0);dr.classList.remove('drag');y0=null;
 if(dy>h*.35||v>.6){dr.style.transform='';close()}
 else if(Math.abs(dy)<6){dr.classList.toggle('full');dr.style.setProperty('--h',dr.classList.contains('full')?'86%':'50%');dr.style.transform=''}
 else if(dy<-30){dr.classList.add('full');dr.style.setProperty('--h','86%');dr.style.transform=''}
 else dr.style.transform=''}
g.addEventListener('pointerup',end);g.addEventListener('pointercancel',end)})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
